    for (int i = 0; i < 5; ++i) {
        factors[i] = n - i;
        factors[i + 5] = n - i;
    }

    long long denominator = 120;
    for (long long &factor : factors) {
        long long g = gcd(factor, denominator);
        factor /= g;
        denominator /= g;
    }

    long long result = 1;
    for (long long factor : factors)
        result *= factor;

    cout << result;
    return 0;
}

